WITH "CHANGE_SET" AS 
( 
    SELECT 
            UPPER(SHA2( "HUB_PK_SRC1"."SRC_BK" || '\\#' || "HUB_PK_SRC1"."ID_BK" || '\\#' || COALESCE("HUB_FK_SRC1"."SRC_BK",
            "UNHUB_FK_SRC1"."SRC_BK")|| '\\#' || COALESCE("HUB_FK_SRC1"."USER_BK","UNHUB_FK_SRC1"."USER_BK")|| '\\#' )) AS "LNA_ZOOMPHONEACTIVITY_USER_HKEY"
        , "SAT_FK_SRC1"."EMAIL" AS "SALESFORCE_EMAIL"
        , "SAT_PK_SRC1"."CALLER_EMAIL" AS "ZOOM_EMAIL"
        , "SAT_PK_SRC1"."ZOOM_PHONE_ACTIVITY_HKEY" AS "ZOOM_PHONE_ACTIVITY_HKEY"
        , COALESCE("HUB_FK_SRC1"."USER_HKEY","UNHUB_FK_SRC1"."USER_HKEY") AS "USER_HKEY"
        , CASE WHEN "MEX_EX_SRC1"."LOAD_CYCLE_ID" IS NULL THEN "BVLCI_SRC1"."LOAD_CYCLE_ID" ELSE "MEX_EX_SRC1"."LOAD_CYCLE_ID"::integer END AS "LOAD_CYCLE_ID"
        , "BVLCI_SRC1"."LOAD_DATE" AS "LOAD_DATE"
        , "HUB_PK_SRC1"."RECORD_SOURCE" AS "RECORD_SOURCE"
    FROM {{ source('eli_dv_rv', 'sat_zm_zoom_phone_activity') }} "SAT_PK_SRC1"
    INNER JOIN {{ source('eli_dv_rv', 'hub_zoom_phone_activity') }} "HUB_PK_SRC1" ON  "SAT_PK_SRC1"."ZOOM_PHONE_ACTIVITY_HKEY" = "HUB_PK_SRC1"."ZOOM_PHONE_ACTIVITY_HKEY"
    LEFT OUTER JOIN {{ source('eli_dv_rv', 'sat_ssc_user') }} "SAT_FK_SRC1" 
        -- Using upper and trim to handle case sensitivity and leading/trailing spaces in email addresses
        ON UPPER(TRIM("SAT_FK_SRC1"."EMAIL")) = UPPER(TRIM("SAT_PK_SRC1"."CALLER_EMAIL"))    --553,266
    LEFT OUTER JOIN {{ source('eli_dv_rv', 'hub_user') }} "HUB_FK_SRC1" ON  "SAT_FK_SRC1"."USER_HKEY" = "HUB_FK_SRC1"."USER_HKEY"
    INNER JOIN "ELIASSEN_DW"."OPENAIR_MTD"."MTD_EXCEPTION_RECORDS" "MEX_SRC1" ON  1 = 1
    INNER JOIN {{ source('eli_dv_rv', 'hub_user') }} "UNHUB_FK_SRC1" ON  "MEX_SRC1"."LOAD_CYCLE_ID"::integer = "UNHUB_FK_SRC1"."LOAD_CYCLE_ID"
    INNER JOIN {{ source('eli_dv_rv', 'sat_ssc_user') }} "UNSAT_FK_SRC1" ON  "UNSAT_FK_SRC1"."USER_HKEY" = "UNHUB_FK_SRC1"."USER_HKEY"
    INNER JOIN "ELIASSEN_DW"."ELIASSEN_FMC"."LOAD_CYCLE_INFO" "BVLCI_SRC1" ON  1 = 1
    LEFT OUTER JOIN "ELIASSEN_DW"."OPENAIR_MTD"."MTD_EXCEPTION_RECORDS" "MEX_EX_SRC1" ON  "MEX_EX_SRC1"."LOAD_CYCLE_ID" = TO_CHAR("HUB_PK_SRC1"."LOAD_CYCLE_ID" )
    WHERE  "MEX_SRC1"."RECORD_TYPE" = 'U'
)
, "MIN_LOAD_TIME" AS 
( 
    SELECT 
            "CHANGE_SET"."LNA_ZOOMPHONEACTIVITY_USER_HKEY" AS "LNA_ZOOMPHONEACTIVITY_USER_HKEY"
        , "CHANGE_SET"."SALESFORCE_EMAIL" AS "SALESFORCE_EMAIL"
        , "CHANGE_SET"."ZOOM_EMAIL" AS "ZOOM_EMAIL"
        , "CHANGE_SET"."LOAD_DATE" AS "LOAD_DATE"
        , "CHANGE_SET"."LOAD_CYCLE_ID" AS "LOAD_CYCLE_ID"
        , "CHANGE_SET"."ZOOM_PHONE_ACTIVITY_HKEY" AS "ZOOM_PHONE_ACTIVITY_HKEY"
        , "CHANGE_SET"."USER_HKEY" AS "USER_HKEY"
        , "CHANGE_SET"."RECORD_SOURCE" AS "RECORD_SOURCE"
        , ROW_NUMBER()OVER(PARTITION BY "CHANGE_SET"."LNA_ZOOMPHONEACTIVITY_USER_HKEY" ORDER BY "CHANGE_SET"."LOAD_CYCLE_ID",
            "CHANGE_SET"."LOAD_DATE") AS "DUMMY"
    FROM "CHANGE_SET" "CHANGE_SET"
)
SELECT 
        "MIN_LOAD_TIME"."LNA_ZOOMPHONEACTIVITY_USER_HKEY" AS "LNA_ZOOMPHONEACTIVITY_USER_HKEY"
    , "MIN_LOAD_TIME"."SALESFORCE_EMAIL" AS "SALESFORCE_EMAIL"
    , "MIN_LOAD_TIME"."ZOOM_EMAIL" AS "ZOOM_EMAIL"
    , "MIN_LOAD_TIME"."ZOOM_PHONE_ACTIVITY_HKEY" AS "ZOOM_PHONE_ACTIVITY_HKEY"
    , "MIN_LOAD_TIME"."USER_HKEY" AS "USER_HKEY"
    , "MIN_LOAD_TIME"."LOAD_CYCLE_ID" AS "LOAD_CYCLE_ID"
    , "MIN_LOAD_TIME"."LOAD_DATE" AS "LOAD_DATE"
    , "MIN_LOAD_TIME"."RECORD_SOURCE" AS "RECORD_SOURCE"
FROM "MIN_LOAD_TIME" "MIN_LOAD_TIME"
WHERE  "MIN_LOAD_TIME"."DUMMY" = 1